using System;using System.Linq;using System.Drawing;using System.IO;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;
namespace ServiceTool{internal static class LogArchivePolishTests{
static IEnumerable<Control> All(Control p){foreach(Control c in p.Controls){yield return c;foreach(var n in All(c))yield return n;}}
[STAThread]static int Main(){int count=0;try{foreach(bool dark in new[]{false,true})using(var f=new LogArchiveDialog(ThemePalette.Create(dark),"Fixture service",Enumerable.Range(0,18).Select(i=>new LogDateFolder{Name=DateTime.Today.AddDays(-i).ToString("yyyy.MM.dd"),Date=DateTime.Today.AddDays(-i)}).ToList(),DateTime.Today)){f.Show();Application.DoEvents();var combo=All(f).OfType<ComboBox>().Single();if(!combo.Items[0].ToString().StartsWith("Только за сегодня")||combo.Items[1].ToString()!="Выбранные даты"||combo.Items[2].ToString()!="Все логи"||combo.SelectedIndex!=0)throw new Exception("Order/default");count++;combo.SelectedIndex=1;Application.DoEvents();var boxes=All(f).OfType<CheckBox>().ToArray();boxes[0].Checked=true;var original=boxes[0];combo.SelectedIndex=2;combo.SelectedIndex=1;Application.DoEvents();if(!ReferenceEquals(original,All(f).OfType<CheckBox>().First())||!original.Checked)throw new Exception("Controls recreated or selection lost");count++;var summary=All(f).OfType<Label>().Single(l=>l.Text.StartsWith("Отметь одну"));if(summary.Text!="Отметь одну или несколько дат. Выбор сохраняется при переходе между страницами.")throw new Exception("Selected text");count++;combo.SelectedIndex=2;if(!All(f).OfType<Label>().Any(l=>l.Text=="Все log-файлы из папки с логами службы, включая вложенные папки."))throw new Exception("All text");count++;combo.SelectedIndex=1;var next=All(f).OfType<Button>().Single(b=>b.Text=="›");next.PerformClick();All(f).OfType<Button>().Single(b=>b.Text=="‹").PerformClick();if(!All(f).OfType<CheckBox>().First().Checked)throw new Exception("Paging selection lost");count++;using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"log-polish-"+dark+".png"));}f.Close();}Console.WriteLine("PASS: "+count+" log order/stable controls/selection/text tests, both themes. No log collection.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}
